const filePath = path.join(__dirname, 'frontend', 'src', 'data', 'exercises.js');
let existingContent = fs.readFileSync(filePath, 'utf-8');

let jsonStr = existingContent.replace('export const exercises = ', '').trim();
if (jsonStr.endsWith(';')) {
  jsonStr = jsonStr.slice(0, -1);
}

const exercises = JSON.parse(jsonStr);
const otherIds = new Set(otherExercises.map(e => e.id));
const filteredExercises = exercises.filter(e => !otherIds.has(e.id));
filteredExercises.push(...otherExercises);

const fileContent = 'export const exercises = ' + JSON.stringify(filteredExercises, null, 2) + ';\n';
fs.writeFileSync(filePath, fileContent, 'utf-8');

console.log(otherExercises.length + ' supplementary exercises were processed. Final total number of exercises in exercises.js is ' + filteredExercises.length + '.');
